#!/usr/bin/env node
/**
 * Embeds the admin operations UI (a single self-contained HTML file) into a
 * committed TypeScript module, so the published `dist` needs no asset copying and
 * the server can serve the UI from a string constant.
 *
 * Source : src/admin-ui/ui.html
 * Output : src/http/admin-ui.generated.ts   (committed; regenerated by prebuild/pretest)
 *
 * Escaping is delegated to JSON.stringify, which safely encodes backticks, `${}`,
 * quotes and newlines into a valid string literal.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const SRC = resolve(here, '../src/admin-ui/ui.html');
const OUT = resolve(here, '../src/http/admin-ui.generated.ts');

const html = readFileSync(SRC, 'utf8');
const bytes = Buffer.byteLength(html, 'utf8');

const banner =
  '// AUTO-GENERATED FILE — DO NOT EDIT.\n' +
  '// Source: src/admin-ui/ui.html — regenerate with `yarn embed:ui` (runs on prebuild/pretest).\n' +
  '/* eslint-disable */\n';

const body =
  banner +
  'export const ADMIN_UI_HTML: string = ' + JSON.stringify(html) + ';\n' +
  'export const ADMIN_UI_BYTES = ' + bytes + ';\n';

writeFileSync(OUT, body, 'utf8');
process.stdout.write(`embed-admin-ui: ${bytes} bytes -> src/http/admin-ui.generated.ts\n`);
